	// An OCR word of page 1 over x0..x1, y 100..800 (ink, not ascent and descent), of up to three letters, its feature row set. Answers its row.
	var ts int32 = atText(et, a, b, c)
	var n int32 = 2
	var w int32 = evidence.OwNew(ow, 1, x0, 100, x1, 800, x0, 800, x1, 800, 0, 0, ts, 2, 0, 888, -1)
	var f int32 = evidence.FeNew(feats, evidence.EaOwords(), w)
	if c > 0 {
		n = 3
	}
	evidence.OwSet(ow, w, 12, n)
	evidence.OwSet(ow, w, evidence.HdFeat(), f)
	evidence.FeSet(feats, f, evidence.XoConf(), 888)
	evidence.FeSet(feats, f, evidence.XoImplausible(), implausible)
